// Last full week vs the 8 weeks before, per branch and metric (code, not AI). A change is flagged when it
// is at least `anomaly_z` standard deviations from the average AND at least `anomaly_min_change_pct`
// away from it, and the numbers aren't tiny.
// ---- lib-ilf.js (included by build.py): shared helpers for the Ironleaf workflows ----
const TZ = 'Europe/London';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const settingsOf = items => Object.fromEntries(items.map(i => i.json).filter(r => r && r.key).map(r => [r.key, r.value]));
const parseJson = (s, d) => { try { return typeof s === 'string' ? JSON.parse(s) : (s === null || s === undefined ? d : s); } catch (e) { return d; } };
const clip = (t, n) => { t = String(t || '').trim().replace(/\.$/, ''); return t.length <= n ? t : t.slice(0, n).replace(/\s+\S*$/, '') + '…'; };
const nowIso = () => DateTime.now().setZone(TZ).toISO();
function aiJson(res) {
  if (!res || res.error) return null;
  const msg = (res.output || []).find(o => o && o.type === 'message');
  const part = msg && (msg.content || []).find(c => c && c.type === 'output_text');
  let t = part ? part.text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  return t && typeof t === 'object' ? t : null;
}
function emailHtml(company, paragraphs, extraHtml) {
  const p = paragraphs.filter(Boolean).map(t => '<p style="margin:0 0 14px;text-align:left">' + t + '</p>').join('');
  return '<div style="font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#1c1f26;max-width:600px;text-align:left">'
    + '<div style="font-weight:800;font-size:13px;letter-spacing:1.5px;text-transform:uppercase;color:#d9480f;margin:0 0 18px">' + esc(company) + '</div>'
    + p + (extraHtml || '') + '</div>';
}
// ---- end lib-ilf.js ----
const s = settingsOf($('Read Settings').all());
const rows = (() => { const r = $input.first().json.rows; return Array.isArray(r) ? r : JSON.parse(r || '[]'); })();
const Z = Number(s.anomaly_z || 2), MIN = Number(s.anomaly_min_change_pct || 15);
const METRICS = { check_ins: 'check-ins', new_members: 'new members', cancellations: 'cancellations', failed_payments: 'failed payments', revenue: 'revenue (£)' };
const weeks = [...new Set(rows.map(r => r.week))].sort();
const last = weeks[weeks.length - 1];
const flags = [], totals = {};
for (const branch of [...new Set(rows.map(r => r.branch))]) {
  const br = rows.filter(r => r.branch === branch);
  for (const m of Object.keys(METRICS)) {
    const now = Number((br.find(r => r.week === last) || {})[m] || 0);
    const before = br.filter(r => r.week !== last).map(r => Number(r[m]));
    const mean = before.reduce((a, b) => a + b, 0) / before.length;
    const sd = Math.sqrt(before.reduce((a, b) => a + (b - mean) ** 2, 0) / before.length) || 1;
    const z = (now - mean) / Math.max(sd, 1);
    const pct = mean ? 100 * (now - mean) / mean : 0;
    totals[m] = totals[m] || { last: 0, usual: 0 };
    totals[m].last += now; totals[m].usual += mean;
    if (Math.abs(z) >= Z && Math.abs(pct) >= MIN && (mean >= 3 || now >= 5)) {
      flags.push({ branch, metric: METRICS[m], last_week: Math.round(now * 100) / 100, usual: Math.round(mean * 10) / 10, change_pct: Math.round(pct), z: Math.round(z * 10) / 10 });
    }
  }
}
flags.sort((a, b) => Math.abs(b.z) - Math.abs(a.z));
const weekLabel = DateTime.fromISO(last).toFormat('d LLL') + ' to ' + DateTime.fromISO(last).plus({ days: 6 }).toFormat('d LLL yyyy');
const prompt = 'Last week: ' + weekLabel + '.\n\nFlagged changes (last week vs the average of the 8 weeks before):\n'
  + (flags.length ? flags.map(f => '- ' + f.branch + ', ' + f.metric + ': ' + f.last_week + ' vs usual ' + f.usual + ' (' + (f.change_pct > 0 ? '+' : '') + f.change_pct + '%, z = ' + f.z + ')').join('\n') : '- none')
  + '\n\nWhole chain last week vs usual:\n' + Object.entries(totals).map(([m, t]) => '- ' + METRICS[m] + ': ' + Math.round(t.last) + ' vs ' + Math.round(t.usual)).join('\n');
return [{ json: { week: last, week_label: weekLabel, flags, totals, prompt } }];

// The Monday email and the saved report.
// ---- lib-ilf.js (included by build.py): shared helpers for the Ironleaf workflows ----
const TZ = 'Europe/London';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const settingsOf = items => Object.fromEntries(items.map(i => i.json).filter(r => r && r.key).map(r => [r.key, r.value]));
const parseJson = (s, d) => { try { return typeof s === 'string' ? JSON.parse(s) : (s === null || s === undefined ? d : s); } catch (e) { return d; } };
const clip = (t, n) => { t = String(t || '').trim().replace(/\.$/, ''); return t.length <= n ? t : t.slice(0, n).replace(/\s+\S*$/, '') + '…'; };
const nowIso = () => DateTime.now().setZone(TZ).toISO();
function aiJson(res) {
  if (!res || res.error) return null;
  const msg = (res.output || []).find(o => o && o.type === 'message');
  const part = msg && (msg.content || []).find(c => c && c.type === 'output_text');
  let t = part ? part.text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  return t && typeof t === 'object' ? t : null;
}
function emailHtml(company, paragraphs, extraHtml) {
  const p = paragraphs.filter(Boolean).map(t => '<p style="margin:0 0 14px;text-align:left">' + t + '</p>').join('');
  return '<div style="font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#1c1f26;max-width:600px;text-align:left">'
    + '<div style="font-weight:800;font-size:13px;letter-spacing:1.5px;text-transform:uppercase;color:#d9480f;margin:0 0 18px">' + esc(company) + '</div>'
    + p + (extraHtml || '') + '</div>';
}
// ---- end lib-ilf.js ----
const s = settingsOf($('Read Settings').all());
const f = $('Flag Changes').first().json;
const x = aiJson($input.first().json) || { headline: f.flags.length ? f.flags.length + ' unusual changes last week.' : 'A normal week.', items: [] };
const cell = 'padding:6px 10px;border-bottom:1px solid #eee;text-align:left;font-size:13px';
const worse = g => /cancellation|failed/.test(g.metric) ? g.change_pct > 0 : g.change_pct < 0;
const rows = f.flags.map(g => '<tr><td style="' + cell + '"><b>' + esc(g.branch) + '</b></td><td style="' + cell + '">' + esc(g.metric) + '</td><td style="' + cell + '">' + g.last_week + '</td><td style="' + cell + '">' + g.usual + '</td><td style="' + cell + ';color:' + (worse(g) ? '#c92a2a' : '#2b8a3e') + '"><b>' + (g.change_pct > 0 ? '+' : '') + g.change_pct + '%</b></td></tr>').join('');
const items = x.items.map(i => '<li style="margin:0 0 8px"><b>' + esc(i.branch) + ', ' + esc(i.metric) + ':</b> ' + esc(i.what) + '<br><span style="color:#666">Worth checking: ' + esc(i.check) + '</span></li>').join('');
const link = (s.base_url || 'http://localhost:5678') + '/webhook/ironleaf/chat';
const html = emailHtml(s.company || 'Ironleaf Fitness', [
  'Good morning ' + esc((s.owner_name || '').split(' ')[0]) + '. Here\'s what stood out in the week of ' + esc(f.week_label) + '.',
  '<b>' + esc(x.headline) + '</b>'
], (rows ? '<table style="border-collapse:collapse;margin:0 0 16px"><tr>' + ['Branch', 'Metric', 'Last week', 'Usual', 'Change'].map(h => '<th style="' + cell + ';color:#999;font-size:12px">' + h + '</th>').join('') + '</tr>' + rows + '</table>' : '')
  + (items ? '<ul style="padding-left:18px;margin:0 0 16px;text-align:left">' + items + '</ul>' : '')
  + '<p style="font-size:12px;color:#999;text-align:left">"Usual" is the average of the 8 weeks before. Flagged when at least 2 standard deviations and 15% away from it. <a href="' + esc(link) + '" style="color:#d9480f">Ask the data assistant</a> to dig in.</p>');
return [{ json: {
  email: { to: s.owner_email, subject: 'Week of ' + f.week_label + ': ' + clip(x.headline, 70), html, kind: 'weekly_anomalies', ref: f.week },
  report: { kind: 'weekly_anomalies', period: f.week, summary: x.headline, data_json: JSON.stringify({ flags: f.flags, totals: f.totals, items: x.items }), created_at: nowIso() }
} }];
